<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
auth();publicHeader('Gestión y emisión de certificados');
$id=(int)($_GET['event_id']??0);$search=trim($_GET['search']??'');$where=["r.status='Pagado'"];$args=[];
if($id){$where[]='r.event_id=?';$args[]=$id;}if($search!==''){$where[]='(CONCAT(r.first_name,\' \',r.last_name) LIKE ? OR r.ci LIKE ?)';array_push($args,'%'.$search.'%','%'.$search.'%');}
$page=max(1,(int)($_GET['page']??1));$count=(int)q('SELECT COUNT(*) FROM registrations r WHERE '.implode(' AND ',$where),$args)->fetchColumn();
$rows=all('SELECT r.*,e.name event_name FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where).' ORDER BY r.last_name,r.first_name LIMIT 50 OFFSET '.(($page-1)*50),$args);
?>
<div class="card p-4"><p>Esta ventana permite emitir e imprimir certificados. Registre la asistencia del participante antes de emitirlos.</p><form method="get"><input type="hidden" name="p" value="list"><div class="row"><div class="col-md-6"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$id);?></div><div class="col-md-6"><?php field('search','Nombre, apellido o CI',$search,'text',false);?></div></div><button class="btn btn-primary">Buscar participantes</button></form></div>
<div class="card p-4"><p><?=e($count)?> participantes con pago confirmado</p><div class="table-responsive"><table class="table"><tr><th>Participante</th><th>Evento</th><th>Asistencia</th><th>Certificado</th><th>Acciones</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e(nombreParticipante($r))?></b><br>CI <?=e($r['ci'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['attended_at']??'Sin registrar')?></td><td><?=e($r['certificate_issued_at']??'Sin emitir')?></td><td><form method="post" action="<?=certificateUrl('p=list&event_id='.$id)?>" target="_blank"><?=csrf()?><input type="hidden" name="action" value="issue"><input type="hidden" name="token" value="<?=e($r['token'])?>"><button class="btn btn-primary btn-sm" <?=$r['attended_at']?'':'disabled'?>>Emitir / imprimir ↗</button></form><?php if($r['certificate_issued_at']):?><a class="btn btn-outline-primary btn-sm mt-2" target="_blank" rel="noopener" href="<?=publicUrl('p=verify&c='.$r['certificate_token'])?>">Validar QR</a><?php endif?></td></tr><?php endforeach?></table></div><div><?php if($page>1):?><a class="btn btn-outline-primary" href="<?=certificateUrl(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">Anterior</a><?php endif?> Página <?=$page?><?php if($page*50<$count):?> <a class="btn btn-outline-primary" href="<?=certificateUrl(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Siguiente</a><?php endif?></div></div>
<?php publicFooter();
